namespace Ritm {
 public sealed class SettingsWindow:Window {
  readonly WrapPanel paletteChoices=new WrapPanel();readonly Store store;readonly GoogleDriveClient drive;readonly Action changed,sync;readonly TextBlock account,status;readonly Button login,import,disconnect;bool connecting;
  public SettingsWindow(Window owner,Store data,GoogleDriveClient google,Action onChange,Action onSync){
   if(owner!=null)Owner=owner;store=data;drive=google;changed=onChange;sync=onSync;Title="Настройки · Ритм";Width=620;Height=750;MinWidth=500;MinHeight=550;WindowStartupLocation=WindowStartupLocation.CenterOwner;if(owner!=null)Icon=owner.Icon;Background=UI.Canvas;
   var panel=new StackPanel{Margin=new Thickness(27),Background=UI.Canvas};Content=new ScrollViewer{Content=panel,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};panel.Children.Add(UI.Text("Настройки",26,null,true));UI.Gap(panel,21);
   panel.Children.Add(UI.Text("Оформление",16,null,true));UI.Gap(panel,12);var themes=new WrapPanel();themes.Children.Add(UI.Button("Светлая",()=>{store.SetTheme("light");changed();RenderPalettes();}));themes.Children.Add(UI.Button("Тёмная",()=>{store.SetTheme("dark");changed();RenderPalettes();}));panel.Children.Add(themes);UI.Gap(panel,18);panel.Children.Add(UI.Text("Палитра",12,UI.Muted,true));UI.Gap(panel,11);panel.Children.Add(paletteChoices);RenderPalettes();UI.Gap(panel,14);var motion=new CheckBox{Content="Плавные анимации интерфейса",IsChecked=!store.Settings.ReduceMotion};motion.Click+=delegate{store.Settings.ReduceMotion=motion.IsChecked!=true;Fx.Enabled=!store.Settings.ReduceMotion;store.SaveLocalPreferences();};panel.Children.Add(motion);UI.Gap(panel,24);
   panel.Children.Add(TextSizeSettings());UI.Gap(panel,24);panel.Children.Add(NotificationSettings());UI.Gap(panel,24);
   var cloudPanel=new StackPanel{Margin=new Thickness(0,14,0,0)};
   cloudPanel.Children.Add(UI.Text("Google Диск",16,null,true));UI.Gap(cloudPanel,8);cloudPanel.Children.Add(UI.Text("Ритм хранит синхронизацию в своей закрытой области на вашем Диске. Вход открывается в обычном браузере. Приложение Google Диска на компьютере не требуется.",12,UI.Muted));UI.Gap(cloudPanel,13);
   account=UI.Text("",12);cloudPanel.Children.Add(account);UI.Gap(cloudPanel,12);var buttons=new WrapPanel();login=UI.Button("Войти через Google",Login,true);buttons.Children.Add(login);disconnect=UI.Button("Отключить",()=>{drive.Disconnect();Update();changed();});buttons.Children.Add(disconnect);cloudPanel.Children.Add(buttons);UI.Gap(cloudPanel,10);status=UI.Text("",11,UI.Muted);cloudPanel.Children.Add(status);UI.Gap(cloudPanel,10);
   var configure=new WrapPanel();import=UI.Button("Импортировать OAuth JSON",ImportClient);configure.Children.Add(import);configure.Children.Add(UI.Button("Настроить с нуля",Setup));cloudPanel.Children.Add(configure);UI.Gap(cloudPanel,8);cloudPanel.Children.Add(UI.Text("При подключении текущие локальные задачи и проекты будут синхронизированы с выбранным аккаунтом. Отключение сохраняет локальные задачи и данные на Диске.",10,UI.Muted));
   panel.Children.Add(new Expander{Header="Синхронизация (настройка отложена)",Content=cloudPanel,Foreground=UI.Muted});
   UI.Gap(panel,26);panel.Children.Add(UI.Text("Резервная копия",16,null,true));UI.Gap(panel,9);var backup=new WrapPanel();backup.Children.Add(UI.Button("Экспорт JSON",Export));backup.Children.Add(UI.Button("Импорт JSON",Import));panel.Children.Add(backup);UI.Gap(panel,8);panel.Children.Add(UI.Text("Импорт добавляет новые задачи; повторный импорт создаёт копии.",10,UI.Muted));
   UI.Gap(panel,25);panel.Children.Add(UI.Text("Локальные данные",16,null,true));UI.Gap(panel,8);panel.Children.Add(UI.Text("Задачи доступны без сети. Токены Google зашифрованы для текущего пользователя Windows. Предыдущие версии задач остаются в истории.",11,UI.Muted));UI.Gap(panel,10);var folders=new WrapPanel();folders.Children.Add(UI.Button("Папка данных",()=>Open(store.Root)));folders.Children.Add(UI.Button("История",()=>Open(Path.Combine(store.Root,"history"))));panel.Children.Add(folders);
   UI.Gap(panel,24);var advanced=new Expander{Header="Дополнительно: обмен через папку",Foreground=UI.Muted};var extra=new StackPanel{Margin=new Thickness(0,12,0,0)};extra.Children.Add(UI.Text("При прямом подключении Google этот режим обычно не нужен.",11,UI.Muted));UI.Gap(extra,10);extra.Children.Add(UI.Button("Выбрать общую папку",ChooseFolder));extra.Children.Add(UI.Button("Отключить обмен через папку",()=>{store.SetSync(null);changed();}));advanced.Content=extra;panel.Children.Add(advanced);UI.Gap(panel,20);panel.Children.Add(UI.Button("Готово",()=>Close()));Closing+=delegate{if(connecting)drive.CancelLogin();};Update();
  }
  static Style TextScaleStyle(){return (Style)XamlReader.Parse(@"<Style xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='Slider'><Setter Property='Height' Value='24'/><Setter Property='FocusVisualStyle' Value='{x:Null}'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='Slider'><Grid Margin='7,0'><Border Height='6' CornerRadius='3' Background='{DynamicResource Line}' VerticalAlignment='Center'/><Track x:Name='PART_Track' VerticalAlignment='Center'><Track.DecreaseRepeatButton><RepeatButton Command='Slider.DecreaseLarge' Focusable='False'><RepeatButton.Template><ControlTemplate TargetType='RepeatButton'><Border Height='6' CornerRadius='3' Background='{DynamicResource Accent}'/></ControlTemplate></RepeatButton.Template></RepeatButton></Track.DecreaseRepeatButton><Track.IncreaseRepeatButton><RepeatButton Command='Slider.IncreaseLarge' Focusable='False'><RepeatButton.Template><ControlTemplate TargetType='RepeatButton'><Border Background='Transparent' Height='20'/></ControlTemplate></RepeatButton.Template></RepeatButton></Track.IncreaseRepeatButton><Track.Thumb><Thumb Width='16' Height='16'><Thumb.Template><ControlTemplate TargetType='Thumb'><Border CornerRadius='8' Background='{DynamicResource Accent}' BorderBrush='{DynamicResource Paper}' BorderThickness='2'/></ControlTemplate></Thumb.Template></Thumb></Track.Thumb></Track></Grid></ControlTemplate></Setter.Value></Setter></Style>");}
  UIElement TextSizeSettings(){var panel=new StackPanel();panel.Children.Add(UI.Text("Размер текста",16,null,true));Action<string,bool> add=(label,sidebar)=>{UI.Gap(panel,10);var header=UI.Text("",12,UI.Muted);panel.Children.Add(header);int saved=sidebar?store.Settings.SidebarTextScale:store.Settings.MainTextScale;var slider=new Slider{Minimum=80,Maximum=120,TickFrequency=1,IsSnapToTickEnabled=false,Style=TextScaleStyle(),Value=saved>=80&&saved<=120?saved:80,Margin=new Thickness(0,6,0,0)};header.Text=label+" · "+(int)slider.Value+"%";slider.ValueChanged+=(sender,e)=>{int value=(int)slider.Value;header.Text=label+" · "+value+"%";if(sidebar)store.Settings.SidebarTextScale=value;else store.Settings.MainTextScale=value;store.SaveLocalPreferences();changed();};panel.Children.Add(slider);};add("Боковая панель",true);add("Основная область",false);return panel;}
  // Переключатели строятся по реестру Notifications.All: новый вид уведомления появляется здесь без правок окна.
  UIElement NotificationSettings(){
   var p=new StackPanel();p.Children.Add(UI.Text("Уведомления",16,null,true));UI.Gap(p,8);p.Children.Add(UI.Text("Когда окно Ритма открыто, уведомление появляется внизу справа; когда свёрнуто или неактивно — в уведомлениях Windows.",11,UI.Muted));UI.Gap(p,12);
   var prefs=store.Settings;var all=new CheckBox{Content="Показывать уведомления Ритма",IsChecked=Notifications.Enabled(prefs),FontWeight=FontWeights.SemiBold};p.Children.Add(all);UI.Gap(p,10);
   var kinds=new StackPanel{Margin=new Thickness(24,0,0,0)};
   foreach(var kind in Notifications.All){var k=kind;var box=new CheckBox{Content=k.Title,IsChecked=Notifications.Choice(prefs,k),ToolTip=k.Description};System.Windows.Automation.AutomationProperties.SetName(box,"Уведомление: "+k.Title);box.Click+=delegate{Notifications.Set(prefs,k,box.IsChecked==true);store.SaveLocalPreferences();};kinds.Children.Add(box);var hint=UI.Text(k.Description,10,UI.Muted);hint.Margin=new Thickness(28,2,0,9);kinds.Children.Add(hint);}
   var inApp=new CheckBox{Content="Только внутри окна Ритма, без уведомлений Windows",IsChecked=prefs.NotificationsInAppOnly,Margin=new Thickness(0,4,0,0)};inApp.Click+=delegate{prefs.NotificationsInAppOnly=inApp.IsChecked==true;store.SaveLocalPreferences();};kinds.Children.Add(inApp);
   kinds.IsEnabled=all.IsChecked==true;all.Click+=delegate{prefs.NotificationsMuted=all.IsChecked!=true;kinds.IsEnabled=!prefs.NotificationsMuted;store.SaveLocalPreferences();};p.Children.Add(kinds);return p;
  }
  void RenderPalettes(){paletteChoices.Children.Clear();foreach(var palette in UI.Palettes){var option=palette;bool selected=(store.Settings.Palette??"violet")==palette.Id;var p=new StackPanel();var swatches=new StackPanel{Orientation=Orientation.Horizontal,Margin=new Thickness(0,0,0,10)};var colors=UI.Dark?palette.Dark:palette.Light;foreach(int index in new[]{0,1,3})swatches.Children.Add(new Border{Width=19,Height=19,CornerRadius=new CornerRadius(10),Background=new System.Windows.Media.SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString(colors[index])),BorderBrush=UI.Line,BorderThickness=new Thickness(1),Margin=new Thickness(0,0,4,0)});p.Children.Add(swatches);p.Children.Add(UI.Text(palette.Name,11,null,true));var b=UI.Button("",()=>{store.SetPalette(option.Id);UI.SetPalette(option.Id);changed();RenderPalettes();});b.Content=p;b.Width=100;b.Padding=new Thickness(11,13,11,12);b.Margin=new Thickness(0,0,9,9);b.HorizontalContentAlignment=HorizontalAlignment.Left;b.Background=selected?UI.B("#E9EDE1"):UI.Paper;b.BorderBrush=selected?UI.Accent:UI.Line;b.BorderThickness=new Thickness(selected?2:1);b.ToolTip="Палитра «"+palette.Name+"»";paletteChoices.Children.Add(b);}}
  void Update(){account.Text=drive.IsConnected?"Google Диск подключён":drive.IsConfigured?"OAuth настроен · можно войти":"Для первого входа нужна регистрация приложения в Google Cloud";login.IsEnabled=drive.IsConfigured&&!drive.IsConnected&&!connecting;disconnect.IsEnabled=drive.IsConnected&&!connecting;import.IsEnabled=!connecting&&!drive.IsConnected;}
  async void Login(){if(connecting)return;connecting=true;Update();status.Text="Ожидаем подтверждение в браузере…";try{await drive.ConnectAsync();status.Text="Google Диск подключён. Запускаем синхронизацию.";sync();}catch(Exception e){status.Text=e.Message;}finally{connecting=false;Update();changed();}}
  void ImportClient(){var dialog=new Microsoft.Win32.OpenFileDialog{Title="OAuth-клиент Google Desktop app",Filter="JSON|*.json"};if(dialog.ShowDialog(this)!=true)return;try{drive.ImportConfiguration(dialog.FileName);status.Text="Настройки импортированы. Теперь можно войти через Google.";Update();}catch(Exception e){Error(e);}}
  void Setup(){
   var w=new Window{Owner=this,Title="Подключить Google Диск · Ритм",Width=680,Height=720,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=UI.Canvas};var p=new StackPanel{Margin=new Thickness(26)};w.Content=new ScrollViewer{Content=p,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};p.Children.Add(UI.Text("Один раз настроить Google",24,null,true));UI.Gap(p,12);p.Children.Add(UI.Text("Google требует собственную регистрацию приложения. Создайте её в своём аккаунте; пароль Google в Ритм вводить не нужно.",12,UI.Muted));
   AddStep(p,"1. Создайте проект «Ритм»","Выберите или создайте проект в Google Cloud.","https://console.cloud.google.com/projectcreate");
   AddStep(p,"2. Включите Google Drive API","Убедитесь, что выбран проект «Ритм», затем нажмите Enable / Включить.","https://console.cloud.google.com/apis/library/drive.googleapis.com");
   AddStep(p,"3. Настройте Google Auth Platform","Укажите имя приложения, свой email. Audience: External. Если приложение в Testing — добавьте свой Google-аккаунт как Test user. В Data Access добавьте только https://www.googleapis.com/auth/drive.appdata.","https://console.cloud.google.com/auth/overview");
   AddStep(p,"4. Создайте OAuth-клиент","В Clients нажмите Create client, выберите Desktop app, затем скачайте JSON. Не выбирайте Web application.","https://console.cloud.google.com/auth/clients");
   UI.Gap(p,15);p.Children.Add(UI.Text("5. Вернитесь в настройки Ритма",15,null,true));UI.Gap(p,6);p.Children.Add(UI.Text("Импортируйте скачанный JSON и нажмите «Войти через Google». Выберите аккаунт и разрешите доступ к данным Ритма. Служебная область на Диске создастся при первой синхронизации.",12,UI.Muted));UI.Gap(p,13);p.Children.Add(UI.Text("В режиме Testing Google может ограничивать срок выданного доступа. Если приложение попросит, выполните вход снова. Для постоянного использования настройте статус публикации в Google Cloud. Доступ к проекту понадобится и для будущего Android-клиента.",11,UI.Muted));UI.Gap(p,20);p.Children.Add(UI.Button("Открыть Google Cloud",()=>Web("https://console.cloud.google.com/projectcreate"),true));UI.Gap(p,8);p.Children.Add(UI.Button("Готово",()=>w.Close()));w.ShowDialog();
  }
  static void AddStep(Panel p,string title,string description,string url){UI.Gap(p,20);p.Children.Add(UI.Text(title,15,null,true));UI.Gap(p,7);p.Children.Add(UI.Text(description,12,UI.Muted));UI.Gap(p,8);p.Children.Add(UI.Button("Открыть страницу",()=>Web(url)));}
  static void Web(string url){Process.Start(new ProcessStartInfo(url){UseShellExecute=true});}
  static void Open(string path){Process.Start(new ProcessStartInfo("explorer.exe",path){UseShellExecute=true});}
  void ChooseFolder(){using(var d=new System.Windows.Forms.FolderBrowserDialog{Description="Общая папка Ритма",SelectedPath=store.Settings.SyncDirectory??""}){if(d.ShowDialog()!=System.Windows.Forms.DialogResult.OK)return;try{store.SetSync(d.SelectedPath);changed();}catch(Exception e){Error(e);}}}
  void Export(){var d=new Microsoft.Win32.SaveFileDialog{Filter="JSON|*.json",FileName="ritm-"+UI.Date(DateTime.Today)+".json"};if(d.ShowDialog(this)!=true)return;try{store.Export(d.FileName);MessageBox.Show(this,"Резервная копия сохранена.","Ритм");}catch(Exception e){Error(e);}}
  void Import(){var d=new Microsoft.Win32.OpenFileDialog{Filter="JSON|*.json"};if(d.ShowDialog(this)!=true)return;try{var list=store.ReadImport(d.FileName);if(MessageBox.Show(this,"Добавить записей: "+list.Count+"? Будут созданы новые записи.","Ритм",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;store.Import(list);changed();sync();}catch(Exception e){Error(e);}}
  void Error(Exception e){MessageBox.Show(this,e.Message,"Ритм",MessageBoxButton.OK,MessageBoxImage.Information);}
 }
